/** Why listing text is refused for a contact detail (a sure find only; weak ones go to Ops later), or null. */
export function listingContactProblem(s: string | null | undefined): string | null {
  const hit = findContacts(s).find((h) => h.sure);
  return hit ? LISTING_CONTACT_COPY[hit.kind] : null;
}

/** A required listing field: `text()` and no contact details. */
export function listingText(limit: TextLimit, opts: TextOptions = {}) {
  return text(limit, opts).superRefine((s, ctx) => {
    const problem = listingContactProblem(s);
    if (problem) ctx.addIssue({ code: "custom", message: problem });
  });
}

/** An optional listing field (null clears it): `optionalText()` and no contact details. */
export function optionalListingText(limit: TextLimit, opts: TextOptions = {}) {
  return optionalText(limit, opts).superRefine((s, ctx) => {
    const problem = s === null ? null : listingContactProblem(s);
    if (problem) ctx.addIssue({ code: "custom", message: problem });
  });
}

