const hhmm = (what: string) => z.string({ error: `Enter a ${what} time.` }).refine((s) => hhmmToMinutes(s) !== null, `Enter a ${what} time as HH:MM.`);

export const windowInputSchema = z
  .strictObject({
    weekday: z.number({ error: "Pick a day." }).int("Pick a day.").min(0, "Pick a day.").max(6, "Pick a day."),
    start: hhmm("start"),
    end: hhmm("end"),
  })
  .refine((w) => (hhmmToMinutes(w.start) ?? 0) < (hhmmToMinutes(w.end) ?? 0), { message: "End after the start time.", path: ["end"] });

/** `PUT /v1/provider/services/{id}/hours`: the whole week in Manila time; windows on one day may not overlap. */
export const putHoursBodySchema = z
  .strictObject({
    windows: z.array(windowInputSchema, { error: "Set the hours." }).max(7 * WINDOWS_PER_DAY, `Use at most ${WINDOWS_PER_DAY} time ranges a day.`),
    version: versionField,
  })
  .superRefine((b, ctx) => {
    const byDay = new Map<number, { i: number; start: number; end: number }[]>();
    b.windows.forEach((w, i) => {
      const list = byDay.get(w.weekday) ?? [];
      list.push({ i, start: hhmmToMinutes(w.start) ?? 0, end: hhmmToMinutes(w.end) ?? 0 });
      byDay.set(w.weekday, list);
    });
    for (const list of byDay.values()) {
      if (list.length > WINDOWS_PER_DAY) ctx.addIssue({ code: "custom", path: ["windows", list[WINDOWS_PER_DAY]!.i], message: `Use at most ${WINDOWS_PER_DAY} time ranges a day.` });
      const sorted = [...list].sort((a, z2) => a.start - z2.start);
      for (let k = 1; k < sorted.length; k++) {
        if (sorted[k]!.start < sorted[k - 1]!.end) ctx.addIssue({ code: "custom", path: ["windows", sorted[k]!.i, "start"], message: "These hours overlap another range on the same day." });
      }
    }
  });
export type PutHoursBody = z.output<typeof putHoursBodySchema>;

const coordinate = (range: readonly [number, number]) =>
  z
    .number({ error: "Pick the place again." })
    .refine((n) => Number.isFinite(n) && n >= range[0] && n <= range[1], "That place is outside the Philippines.")
    .nullable()
    .optional()
    .transform((v) => (v === undefined || v === null ? null : Math.round(v * 1e6) / 1e6));

export const areaInputSchema = z
  .strictObject({ name: listingText(LIMITS.areaName, { noEmoji: true }), lat: coordinate(PH_BOUNDS.lat), lng: coordinate(PH_BOUNDS.lng) })
  .refine((a) => (a.lat === null) === (a.lng === null), { message: "Pick the place again.", path: ["lat"] });

/**
 * `PUT /v1/provider/services/{id}/areas`: where the service is offered. `city`: one city, no areas. `areas`: a city and
 * 1-30 named areas (no duplicates). `nationwide`: online services only, no city.
 */
export const putAreasBodySchema = z
  .strictObject({
    scope: z.enum(SERVICE_SCOPES, { error: "Choose where you offer it." }),
    cityId: z.number({ error: "Pick a city." }).int("Pick a city.").positive("Pick a city.").nullable().optional(),
    areas: z.array(areaInputSchema, { error: "Add the areas." }).max(CAPS.areasPerService, `Add at most ${CAPS.areasPerService} areas.`).optional().default([]),
    version: versionField,
  })
  .superRefine((b, ctx) => {
    if (b.scope === "nationwide") {
      if (b.cityId !== undefined && b.cityId !== null) ctx.addIssue({ code: "custom", path: ["cityId"], message: "Leave the city out for a nationwide service." });
    } else if (b.cityId === undefined || b.cityId === null) ctx.addIssue({ code: "custom", path: ["cityId"], message: "Pick a city." });
    if (b.scope !== "areas" && b.areas.length) ctx.addIssue({ code: "custom", path: ["areas"], message: "Areas are only for Specific areas." });
    if (b.scope === "areas" && !b.areas.length) ctx.addIssue({ code: "custom", path: ["areas"], message: "Add at least one area, or pick Whole city." });
    const seen = new Set<string>();
    b.areas.forEach((a, i) => {
      const key = a.name.toLowerCase();
      if (seen.has(key)) ctx.addIssue({ code: "custom", path: ["areas", i, "name"], message: "Already added." });
      seen.add(key);
    });
  });
export type PutAreasBody = z.output<typeof putAreasBodySchema>;

/** `POST /v1/provider/services/order`: every one of the seller's (not archived) service ids, each once. */
export const orderBodySchema = z.strictObject({ ids: z.array(uuidSchema, { error: "Send the service ids." }).min(1, "Send the service ids.").max(CAPS.servicesPerSeller, `Send at most ${CAPS.servicesPerSeller} ids.`) });
export type OrderBody = z.output<typeof orderBodySchema>;

export const addPhotoBodySchema = z.strictObject({ mediaId: uuidSchema });
