export const orderPhotosBodySchema = z.strictObject({ mediaIds: z.array(uuidSchema, { error: "Send the photo ids." }).min(1, "Send the photo ids.").max(CAPS.photosPerService, `Send at most ${CAPS.photosPerService} ids.`) });
