// ---- typed client ----

type In<S extends z.ZodType> = z.input<S>;
const enc = encodeURIComponent;

/**
 * The service routes. `base` is `/v1/provider/services` for the provider's own services; team services (W2) use
 * `/v1/provider/teams/{teamId}/services` with the same sub-routes.
 */
export function servicesApi(api: Client, base = "/v1/provider/services") {
  const one = (id: string) => `${base}/${enc(id)}`;
  return {
    list: (): Promise<ApiResult<ServiceList>> => api.get(base, { schema: serviceListSchema }),
    create: (body: In<typeof createServiceBodySchema>): Promise<ApiResult<Service>> => api.post(base, body, { schema: serviceSchema }),
    get: (id: string): Promise<ApiResult<Service>> => api.get(one(id), { schema: serviceSchema }),
    update: (id: string, body: In<typeof patchServiceBodySchema>): Promise<ApiResult<Service>> => api.patch(one(id), body, { schema: serviceSchema }),
    /** archives it: clients can no longer find or book it; bookings keep their details */
    archive: (id: string): Promise<ApiResult<undefined>> => api.delete(one(id), { schema: z.undefined() }),
    /** 422 with `missing[]` / `held[]` when it is not ready */
    publish: (id: string, body?: In<typeof transitionBodySchema>): Promise<ApiResult<Service>> => api.post(`${one(id)}/publish`, body ?? {}, { schema: serviceSchema }),
    pause: (id: string, body?: In<typeof transitionBodySchema>): Promise<ApiResult<Service>> => api.post(`${one(id)}/pause`, body ?? {}, { schema: serviceSchema }),
    order: (ids: string[]): Promise<ApiResult<ServiceList>> => api.post(`${base}/order`, { ids }, { schema: serviceListSchema }),
    addPhoto: (id: string, mediaId: string): Promise<ApiResult<Service>> => api.post(`${one(id)}/photos`, { mediaId }, { schema: serviceSchema }),
    removePhoto: (id: string, mediaId: string): Promise<ApiResult<Service>> => api.delete(`${one(id)}/photos/${enc(mediaId)}`, { schema: serviceSchema }),
    orderPhotos: (id: string, mediaIds: string[]): Promise<ApiResult<Service>> => api.post(`${one(id)}/photos/order`, { mediaIds }, { schema: serviceSchema }),
    setHours: (id: string, body: In<typeof putHoursBodySchema>): Promise<ApiResult<Service>> => api.put(`${one(id)}/hours`, body, { schema: serviceSchema }),
    setAreas: (id: string, body: In<typeof putAreasBodySchema>): Promise<ApiResult<Service>> => api.put(`${one(id)}/areas`, body, { schema: serviceSchema }),
  };
}
